#include <math.h>
int main(){int W=2400,H=1800,x,y;FILE*f=fopen("reconstructed.ppm","wb");fprintf(f,"P6\n%d %d\n255\n",W,H);
for(y=0;y<H;y++)for(x=0;x<W;x++){double X=x-1199.5,Y=y-899.5,r,g,b;
if(Y<=0){double t=(double)y/900, q=1-t, a=fabs(X)/1200; r=191-45*pow(q,1.35)+13*a*a*pow(q,1.1);g=217-27*pow(q,1.2)+7*a*a*pow(q,1.1);b=255;}
else{double u=1.5*X/Y,v=675/Y-.5;int k=(int)floor(u)+(int)floor(v);int c=(k&1)?67:152;
/* cast shadow, elongated toward the lower left */
double sx=X-(-260),sy=Y-360,co=.94,si=.342,xx=(sx*co+sy*si)/520,yy=(-sx*si+sy*co)/105;
if(xx*xx+yy*yy<1&&X<180){c=c*.30;}
/* nearly circular red ball */
double dx=X,dy=Y-95,rr=dx*dx+dy*dy;if(rr<185*185){double z=sqrt(1-rr/(185.*185)), nx=dx/185,ny=dy/185;double d=nx*.42-ny*.60+z*.68; if(d<0)d=0; d=.22+.78*d; r=198*d;g=39*d;b=39*d;}else r=g=b=c;}
unsigned char q[3];q[0]=r<0?0:r>255?255:r;q[1]=g<0?0:g>255?255:g;q[2]=b<0?0:b>255?255:b;fwrite(q,1,3,f);}fclose(f);}

